package com.andye.warmod.radar.client;
import com.andye.warmod.radar.client.gui.RadarScreen;import com.andye.warmod.radar.network.*;import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientLevelEvents;import net.fabricmc.fabric.api.client.networking.v1.*;import net.minecraft.client.Minecraft;
public final class ClientRadarNetworking{private static boolean registered;private ClientRadarNetworking(){}public static void register(){if(registered)return;ClientPlayNetworking.registerGlobalReceiver(ClientboundOpenRadarPayload.TYPE,(p,c)->{ClientRadarState.INSTANCE.open(p);Minecraft.getInstance().gui.setScreen(new RadarScreen());});ClientPlayNetworking.registerGlobalReceiver(ClientboundCloseRadarPayload.TYPE,(p,c)->{ClientRadarState.INSTANCE.clear();if(Minecraft.getInstance().gui.screen() instanceof RadarScreen)Minecraft.getInstance().gui.setScreen(null);});ClientPlayNetworking.registerGlobalReceiver(ClientboundRadarSnapshotPayload.TYPE,(p,c)->ClientRadarState.INSTANCE.snapshot(p));ClientPlayNetworking.registerGlobalReceiver(ClientboundRadarTrackUpsertPayload.TYPE,(p,c)->ClientRadarState.INSTANCE.upsert(p));ClientPlayNetworking.registerGlobalReceiver(ClientboundRadarTrackRemovePayload.TYPE,(p,c)->ClientRadarState.INSTANCE.remove(p));ClientPlayNetworking.registerGlobalReceiver(ClientboundRadarImpactPayload.TYPE,(p,c)->ClientRadarState.INSTANCE.impact(p));ClientPlayNetworking.registerGlobalReceiver(ClientboundRadarInterceptionPayload.TYPE,(p,c)->ClientRadarState.INSTANCE.interception(p));ClientPlayConnectionEvents.DISCONNECT.register((h,client)->ClientRadarState.INSTANCE.clear());ClientLevelEvents.AFTER_CLIENT_LEVEL_CHANGE.register((client,level)->ClientRadarState.INSTANCE.clear());registered=true;}public static void requestOpen(){if(ClientPlayNetworking.canSend(ServerboundOpenRadarPayload.TYPE))ClientPlayNetworking.send(new ServerboundOpenRadarPayload());}public static void close(){if(ClientPlayNetworking.canSend(ServerboundCloseRadarPayload.TYPE))ClientPlayNetworking.send(new ServerboundCloseRadarPayload());ClientRadarState.INSTANCE.clear();}}
